    excerpt: "鳥栖警察署の公表によると、10月1日午後3時50分ごろ、佐賀県鳥栖市永吉町の路上で児童が知らない男性から後をつけられた。男は50歳代くらい、身長170センチくらいの小太りで、白髪交じりの黒色短髪、白色半袖Tシャツに黒色長ズボン。同署が警戒を呼びかけている。",
    content: `## 事案の概要

佐賀県警察・鳥栖警察署が公表した不審者情報によると、2026年10月1日（木）午後3時50分ごろ、佐賀県鳥栖市永吉町の路上で、**児童が知らない男性から後をつけられる**事案が発生しました。

### 発生状況（公表されている範囲）

- **日時**：2026年10月1日（木）午後3時50分ごろ
- **場所**：佐賀県鳥栖市永吉町の路上
- **被害者**：児童
- **行為**：知らない男性が後をつけた
- **男の特徴**：年齢50歳代くらい／身長170センチくらい／体格は小太り／頭髪は白髪交じりの黒色短髪／上衣は白色の半袖Tシャツ／下衣は黒色の長ズボン
- **発表**：鳥栖警察署

児童が下校の途中だったかどうかは、確認できた公表内容では明らかになっていません。**午後3時50分は多くの小学校で下校と重なる時間帯**ですが、公表されていないことは書かないでおきます。

### 「つけられる」事案は、子どもが気づきにくい

声をかけられる事案と違い、後をつけられる事案は**子ども自身が気づきにくい**という特徴があります。相手は接触してこないため、「何かされた」という出来事が起きません。だから家に帰ってからも話題にならず、保護者に伝わらないまま終わってしまうことがあります。

鳥栖警察署は、知らない人から後をつけられた場合には**近くの大人に知らせること**、危険を感じたら**大声を出して人に助けを求めること**を子どもに指導するよう呼びかけています。

ここで効くのは、「振り返る場所」を先に決めておくことです。帰り道の決まった地点で一度だけ後ろを見る。それだけで、つけられていることに気づくまでの時間が短くなります。

## そなえの一言

帰り道に「ここで一度振り返る」地点を決めて、今日いっしょに歩いて確かめましょう。

### 保護者・地域にできること

1. **振り返る地点を1か所決める**：曲がり角や店の前など、覚えやすい場所を1つ選ぶ。「いつも後ろを気にする」より実行しやすい
2. **「ついて来られた」も報告してよいと伝える**：何もされていなくても話していい、と先に許可を出しておく。これがないと子どもは黙ってしまう
3. **駆け込める場所を指さす**：永吉町周辺の通学路で、明かりがついていて人がいる場所を子どもと確認しておく
4. **特徴を身近な基準で共有する**：「身長170センチくらい」は、家族の誰と同じくらいかで伝えると子どもに届きやすい

### 出典
- 鳥栖警察署「不審者に注意」（2026年10月1日発生分／佐賀新聞の不審者情報欄で配信）
- ガッコム安全ナビ「佐賀県鳥栖市の不審者・治安情報」（鳥栖警察署の公表情報を配信）`,
