3. **砧周辺を通る子に共有する**：世田谷区砧付近を通学路や習い事の道にしている家庭同士で、特徴を共有し、しばらく複数で帰る日を作る
4. **見かけたらすぐ110番**：特徴に近い男を見かけたときは、近づかず、警察へ通報する

