2. **つきまとわれたときの動作を決める**：後ろをついて来る人に気づいたら、**来た道を戻らず**、人のいる店やこども110番の家に入る、と行き先を先に決めておく
3. **午後4時台の帰り道を一緒に歩く**：この時間帯に子どもがどの道を通っているかを、実際に一緒に歩いて確認する
