1. **「なんとなく怖かった」を歓迎する**：確証がなくても話していい、と明言する。話してくれたときに「気のせいじゃない？」と返さない
2. **逃げ込める場所の道順を確認する**：通学路上のこども110番の家・コンビニ・店舗を、家から学校までの間で1か所ずつ、実際に入り口まで歩いて確認する
3. **振り返って確かめる動作**：後ろが気になったら、立ち止まらずに**歩きながら一度振り返る**、気になったら人のいる方向へ進路を変える、という動作を決めておく
4. **防犯ブザーの点検**：ブザーが鳴るか・電池が残っているかを今夜いっしょに確認する。折尾署も携帯を呼びかけています

