    title: "【兵庫県川西市】下校中の7歳男児が校門付近でひき逃げされ重傷 児童指導員を逮捕",
    excerpt: "川西市多田院の小学校敷地内で8月27日午前11時ごろ、下校中の7歳の男子児童が車にはねられ、頭の骨と右鎖骨を折る重傷を負った。車はそのまま走り去り、兵庫県警は児童指導員の女（53）をひき逃げなどの疑いで逮捕した。",
    content: `## 事案の概要

2026年8月27日（木）午前11時ごろ、兵庫県川西市多田院の小学校の敷地内・正門付近で、下校中だった7歳の男子児童が乗用車にはねられました。児童は搬送時に意識はあったものの、頭の骨と右の鎖骨を折る重傷を負っています。車は救護せずにその場を離れ、兵庫県警は宝塚市の児童指導員の女（53）を過失運転致傷・ひき逃げの疑いで逮捕しました。

### 発生状況（判明している範囲）

- **日時**：2026年8月27日（木）午前11時ごろ
- **場所**：兵庫県川西市多田院の小学校敷地内・正門付近
- **被害者**：下校中の7歳の男子児童
- **けがの程度**：頭の骨・右鎖骨の骨折（重傷）。搬送時に意識はあった
- **逮捕**：宝塚市の児童指導員の女（53）。「はねたことに気付かず救護しなかった」と容疑を否認する一方、「安全確認が不十分だったことで大けがをさせてしまったことに間違いない」と話しているとされる

女は当時、デイサービスを利用する別の児童を迎えに来ていたと説明しています。学校から「児童がひき逃げされた」と110番通報があり、目撃した児童からの情報と防犯カメラの映像をもとに逮捕に至りました。

### 「学校の中だから安全」とは限らない

この事故は通学路の途中ではなく、学校の敷地内・正門のすぐそばで起きています。校門付近は送迎の車、放課後デイサービスの車、業者の車が出入りする場所でもあり、子どもにとっては「もう学校に着いた」「もう学校を出た」と気がゆるむ地点と重なります。

一方で、目撃した子どもたちの証言が逮捕の決め手のひとつになりました。「見たことを大人に伝える」ことが、実際に事案の解明につながっています。

## そなえの一言

校門を出た直後の数十メートルも車が通る場所として、今日いっしょに歩いて確認しましょう。

### 保護者・地域にできること

1. **校門前を歩いて確認**：門を出てから最初の角までを親子で歩き、車がどこから出入りするかを目で確かめる
2. **止まってから歩き出す**：門を出るときは一度立ち止まり、左右と後ろを見てから歩き出す動作を習慣にする
3. **車の前後を横切らない**：停まっている車のすぐ前後は運転席から見えにくい。回り込まず、離れて通る
4. **見たことを伝える**：「あぶないことを見たら、その日のうちに先生かおうちの人に言う」と約束しておく

### 出典
- 讀賣テレビ「小学校の敷地内で男子児童（7）がひき逃げ 児童指導員の女を逮捕」（2026年8月28日）
- サンテレビ「川西市の小学校敷地内で7歳男児をひき逃げ」（2026年8月28日）
- 関西テレビ「『はねたことに気づかなかった』小学生の男児をはねて逃げた疑い」（2026年8月28日）`,
